function firstName(value) {
  return String(value || '').trim().split(/\s+/).filter(Boolean)[0] || '';
}

function regexIntent(text) {
  const normalized = String(text || '');
  if (/\b(pdf|segunda via|2 via|orcamento em pdf|os em pdf|comprovante)\b/.test(normalized)) return 'pdf';
  if (/\b(os|ordem de servico|status da os|acompanhar)\b/.test(normalized)) return 'os';
  if (/\b(orcamento|valor|preco|aprovar orcamento)\b/.test(normalized)) return 'orcamento';
  if (/\b(equipamento|celular|iphone|samsung|notebook|tablet|aparelho|serial|imei)\b/.test(normalized)) return 'equipamento';
  if (/\b(endereco|telefone|pix|horario|localizacao|onde fica|garantia|politica)\b/.test(normalized)) return 'institucional';
  if (/\b(defeito|placa|bateria|tela|reparo|manutencao|tecnico|processador|memoria|windows|android|ios|iphone|tecnologia|como funciona|o que significa)\b/.test(normalized)) return 'tecnica';
  if (/\b(atendente|humano|pessoa|falar com alguem)\b/.test(normalized)) return 'humano';
  if (/\b(oi|ola|bom dia|boa tarde|boa noite)\b/.test(normalized)) return 'saudacao';
  return 'continuidade';
}

function localDateParts(date) {
  return {
    date: new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Fortaleza' }).format(date),
    time: new Intl.DateTimeFormat('pt-BR', {
      timeZone: 'America/Fortaleza',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
    }).format(date),
  };
}

