  return String(value || '').trim().split(/\s+/).filter(Boolean)[0] || '';
}

function compact(text, max = 2400) {
  return String(text || '').replace(/\s+/g, ' ').trim().slice(0, max);
}

const base = safeNodeFirstJson('Interpretar Triagem IA V3');
const conversa = safeNodeFirstJson('Buscar Conversa ERP');
const historicoRows = safeNodeAllJson('Buscar Historico Recente ERP')
  .filter((row) => row && row.id && String(row.mensagem || '').trim() !== '')
  .sort((a, b) => Number(a.id) - Number(b.id))
  .slice(-8);
const equipamentosRows = safeNodeAllJson('Buscar Equipamentos ERP').filter((row) => row && row.id);
const osRows = safeNodeAllJson('Buscar OS ERP').filter((row) => row && row.id);
const orcRows = safeNodeAllJson('Buscar Orcamentos ERP').filter((row) => row && row.id);

const cliente = base.cliente || {};
const canShareSensitive = base.identityStatus === 'confirmado' && base.needsSensitiveValidation !== true;
const clienteEncontrado = base.clienteEncontrado === true;
const preferredGreetingName = base.preferredGreetingName || firstName(base.pushName) || '';

const historicoFormatado = historicoRows.length > 0
  ? historicoRows.map((row) => `${String(row.created_at || '').replace('T', ' ').slice(0, 16)} | ${row.origem_resumida}: ${compact(row.mensagem, 240)}`).join('\n')
  : 'Sem historico recente da conversa no ERP.';

const equipamentosResumo = equipamentosRows.length > 0
  ? equipamentosRows.map((row) => `${row.marca || '-'} ${row.modelo || '-'} (${row.tipo || '-'}) serie:${row.numero_serie || '-'} imei:${row.imei || '-'}`).join('\n')
  : 'Nenhum equipamento localizado.';

const osResumo = osRows.length > 0
  ? osRows.map((row) => `OS ${row.numero_os || row.numero_os_legado || row.id} | status:${row.status || '-'} | fluxo:${row.estado_fluxo || '-'} | valor:${row.valor_final || '-'} | equipamento:${[row.equip_marca, row.equip_modelo].filter(Boolean).join(' ') || '-'}`).join('\n')
  : 'Nenhuma OS localizada.';

const orcResumo = orcRows.length > 0
  ? orcRows.map((row) => `Orcamento ${row.numero || row.id} | status:${row.status || '-'} | total:${row.total || '-'} | validade:${row.validade_data || '-'} | equipamento:${[row.equip_marca, row.equip_modelo].filter(Boolean).join(' ') || '-'}`).join('\n')
  : 'Nenhum orcamento localizado.';

const safeOperationalContext = canShareSensitive ? [
  'Dados do cliente autorizados para uso na resposta:',
  `Cliente: ${cliente.nome_razao || '-'}`,
  `Email: ${cliente.email || '-'}`,
  `Telefone1: ${cliente.telefone1 || '-'}`,
  `Telefone2: ${cliente.telefone2 || '-'}`,
  `Endereco: ${[cliente.endereco, cliente.numero, cliente.complemento, cliente.bairro, cliente.cidade, cliente.uf].filter(Boolean).join(', ') || '-'}`,
  'Equipamentos:',
  equipamentosResumo,
  'Ordens de servico:',
  osResumo,
  'Orcamentos:',
  orcResumo
].join('\n\n') : 'Nao use nem revele dados operacionais sensiveis do ERP nesta resposta. Se o cliente pedir OS, orcamento, equipamento ou segunda via, peca validacao segura antes de prosseguir.';

const toolGuidance = [
  'Tool buscar_base_institucional_drive: use quando a pergunta for sobre endereco, horarios, PIX, garantia, politicas, procedimentos da assistencia ou qualquer conteudo institucional guardado no Google Drive oficial.',
  'Tool Brave Search: use somente para perguntas tecnicas gerais, causas provaveis, explicacoes sobre defeitos e tecnologia. Nunca use Brave Search para dados operacionais do ERP.',
  'Nao existe busca automatica de PDF/segunda via nesta versao. Se o cliente pedir PDF, seja transparente e oriente que a equipe vai conferir o documento correto apos a validacao necessaria.'
].join(' ');

const systemMessage = [
  `Voce e a atendente virtual da ${base.companyName}.`,
  'Fale como uma pessoa real no WhatsApp: natural, clara, acolhedora e profissional.',
  'Continue a conversa considerando historico recente e memoria.',
  'Nao trate toda mensagem como inicio de atendimento.',
  'Nao invente dados de OS, orcamento, equipamento, PDF ou dados pessoais.',
  'Se needsSensitiveValidation for verdadeiro, sua primeira resposta deve pedir confirmacao de identidade de forma objetiva, sem entregar qualquer dado do ERP.',
  toolGuidance,
  'No maximo uma pergunta objetiva por vez.',
  'Sem markdown. Resposta curta e natural, pronta para WhatsApp.'
].join(' ');

const agentInput = [
  `Evento: ${base.normalizedEventName || base.eventName || '-'}`,
  `Telefone normalizado: ${base.normalizedPhone || '-'}`,
  `Nome no perfil WhatsApp: ${base.pushName || '-'}`,
  `Nome preferido para abordagem: ${preferredGreetingName || '-'}`,
  `Cliente encontrado: ${clienteEncontrado ? 'sim' : 'nao'}`,
  `Identity status: ${base.identityStatus || 'nao_confirmado'}`,
  `Intent detectada: ${base.intentCategory || 'continuidade'}`,
  `Needs sensitive validation: ${base.needsSensitiveValidation ? 'sim' : 'nao'}`,
  `Pergunta tecnica: ${base.isTechnical ? 'sim' : 'nao'}`,
  `Motivo da triagem: ${base.triageReason || '-'}`,
  `Mensagem atual do cliente: ${base.receivedText || '(sem texto)'}`,
  `Conversa atual no ERP: status=${conversa.status || '-'}, aguardando_humano=${conversa.aguardando_humano ?? '-'}, automacao_ativa=${conversa.automacao_ativa ?? '-'}`,
  'Historico recente da conversa:',
  historicoFormatado,
  'Contexto operacional do ERP:',
  safeOperationalContext,
  `Google Drive institucional configurado via fileId: ${base.driveKnowledgeFileId || 'nao_configurado'}`,
  `Brave Search habilitado para tecnico: ${base.technicalSearchEnabled ? 'sim' : 'nao'}`,
  'Responda ao cliente de forma util e segura, sem vazar informacoes de outro cliente.'
