return [{
  json: {
    ...base,
    conversa,
    historicoCount: historicoRows.length,
    equipmentCount: equipamentosRows.length,
    osCount: osRows.length,
    orcamentoCount: orcRows.length,
    openaiSystemMessage: systemMessage,
    agentInput,
    canShareSensitive
  }
}];

const ctx = $('Montar Contexto IA V3').first().json;
const raw = String($json.output || '').trim();

function sanitize(text) {
  return String(text || '').replace(/[*_`#>]+/g, '').replace(/\s+/g, ' ').trim();
}

function splitLongSentence(sentence, maxLen = 260) {
  const parts = [];
  let remaining = sentence.trim();
  while (remaining.length > maxLen) {
    const slice = remaining.slice(0, maxLen + 1);
    let breakAt = Math.max(slice.lastIndexOf('. '), slice.lastIndexOf('! '), slice.lastIndexOf('? '));
    if (breakAt < 100) breakAt = Math.max(slice.lastIndexOf('; '), slice.lastIndexOf(': '), slice.lastIndexOf(', '));
    if (breakAt < 100) breakAt = slice.lastIndexOf(' ');
    if (breakAt < 60) breakAt = maxLen;
    parts.push(remaining.slice(0, breakAt + 1).trim());
    remaining = remaining.slice(breakAt + 1).trim();
  }
  if (remaining) parts.push(remaining);
  return parts;
}

function buildBlocks(text, maxLen = 260) {
  const cleaned = sanitize(text);
  if (!cleaned) return [];
  const sentences = cleaned.split(/(?<=[.!?])\s+/).filter(Boolean);
  const blocks = [];
  let current = '';
  for (const sentence of sentences) {
    if (sentence.length > maxLen) {
      const expanded = splitLongSentence(sentence, maxLen);
      for (const part of expanded) {
        if (!current) {
          current = part;
        } else if ((current + ' ' + part).length <= maxLen) {
          current += ' ' + part;
        } else {
          blocks.push(current.trim());
          current = part;
        }
      }
      continue;
    }
    if (!current) {
      current = sentence;
    } else if ((current + ' ' + sentence).length <= maxLen) {
      current += ' ' + sentence;
    } else {
      blocks.push(current.trim());
      current = sentence;
    }
  }
  if (current) blocks.push(current.trim());
  const normalizedBlocks = blocks.length > 0 ? blocks : [cleaned];
  if (normalizedBlocks.length <= 3) return normalizedBlocks;
  return [normalizedBlocks[0], normalizedBlocks[1], normalizedBlocks.slice(2).join(' ')];
}

let aiReply = sanitize(raw);
const nome = ctx.preferredGreetingName || '';

if (aiReply === '') {
  if (ctx.needsSensitiveValidation) {
    aiReply = nome
      ? `Oi, ${nome}. Antes de te passar esse dado, preciso confirmar sua identidade. Me confirma seu nome completo, por favor.`
      : 'Oi. Antes de te passar esse dado, preciso confirmar sua identidade. Me confirma seu nome completo, por favor.';
  } else if (ctx.intentCategory === 'pdf') {
    aiReply = 'Recebi seu pedido de segunda via. Vou registrar isso aqui e orientar a equipe para conferir o documento correto pra voce.';
  } else if (ctx.hasMedia && !ctx.receivedText) {
    aiReply = `Recebi seu anexo na ${ctx.companyName}. Vou registrar aqui e seguir com o atendimento.`;
  } else if (ctx.clienteEncontrado && nome) {
    aiReply = `Oi, ${nome}. Vi sua mensagem agora. Como posso te ajudar por aqui?`;
  } else {
    aiReply = `Oi. Recebi sua mensagem na ${ctx.companyName}. Como posso te ajudar por aqui?`;
  }
}

const outputBlocks = buildBlocks(aiReply, 260);
return {
  ...ctx,
  aiRawResponse: $json,
  finalReply: aiReply,
  outputBlocks,
  replyMode: 'ai'
};
